CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255) NOT NULL, login VARCHAR(255) NOT NULL, name VARCHAR(255), birthday DATE NOT NULL);
CREATE TABLE IF NOT EXISTS mpa (id INTEGER PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS genres (id INTEGER PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS films (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, description VARCHAR(200), release_date DATE NOT NULL, duration INTEGER NOT NULL, mpa_id INTEGER REFERENCES mpa(id));
CREATE TABLE IF NOT EXISTS film_genres (film_id INTEGER NOT NULL REFERENCES films(id) ON DELETE CASCADE, genre_id INTEGER NOT NULL REFERENCES genres(id), PRIMARY KEY (film_id, genre_id));
CREATE TABLE IF NOT EXISTS likes (film_id INTEGER NOT NULL REFERENCES films(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (film_id, user_id));
CREATE TABLE IF NOT EXISTS friendships (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, friend_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, confirmed BOOLEAN DEFAULT FALSE NOT NULL, PRIMARY KEY (user_id, friend_id));
CREATE INDEX IF NOT EXISTS idx_likes_film ON likes(film_id);
CREATE INDEX IF NOT EXISTS idx_friendships_user ON friendships(user_id);
